custom_css:
@import url('/css/tavernnext-atelier.css');
@import url('/css/tavernnext-mineral.css');

:root {
    --tn-accent: #88cec2;
    --tn-accent-hover: #a0d9cf;
    --tn-accent-soft: rgba(136, 206, 194, 0.15);
    --tn-accent-fill: #8ecfc4;
    --tn-accent-fill-hover: #a2d9d0;
    --tn-accent-contrast: #112c2b;
    --tn-accent-border: #5f9f97;
    --tn-accent-highlight: rgba(255, 255, 255, 0.32);
    --tn-accent-shadow: rgba(0, 0, 0, 0.3);
    --tn-warm: #d6a66d;
    --tn-status-contrast: #101616;
    --tn-surface-0: rgba(24, 32, 36, 0.98);
    --tn-surface-1: rgba(31, 41, 43, 0.98);
    --tn-surface-2: rgba(39, 51, 53, 0.98);
    --tn-surface-solid: #1d2628;
    --tn-field: rgba(16, 23, 25, 0.98);
    --tn-field-hover: #152022;
    --tn-field-highlight: rgba(255, 255, 255, 0.04);
    --tn-hover: rgba(136, 206, 194, 0.1);
    --tn-active: rgba(136, 206, 194, 0.18);
    --tn-selected: rgba(136, 206, 194, 0.14);
    --tn-hairline: rgba(217, 228, 223, 0.12);
    --tn-code-bg: #0c1113;
    --tn-code-text: #d5e0de;
    --tn-danger: #f09aa3;
    --tn-success: #8bd1b5;
    --tn-warning: #e5bd7f;
    --tn-scrollbar: rgba(110, 147, 141, 0.48);
    --tn-shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.28), 0 6px 18px rgba(0, 0, 0, 0.2);
    --tn-shadow-lg: 0 16px 40px rgba(0, 0, 0, 0.46);
}

body { color-scheme: dark !important; }
